"""Corpus requirements and dated annotations, not a corpus-pass checker."""
from pathlib import Path
import json, hashlib
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-corpus-authority-rev1'
SOURCE='docs/planning/PHENOMENON_CORPUS.md'
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def save(p,v):
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
specs=[
 (1,'MANIFEST','Current0.29.0/21 commitment differs from0.28/0.27; membership is obligation, not passing status.','Earlier verdicts retain executed corpus identity; exact requirement or fixture changes require intentional versioning.','ledger-early'),
 (64,'ADAPT','Same model/S0/seed and matched allocation topology; hidden count affects four single-path rules, later diagnostic D read mediates permitted divergence.','Route closure cannot pass vacuously empty. No-dispatch, admission failure, empty rule set and per-rule NoStateChange differ. Zero baseline omitted; faster reacquisition needs separate semantic state, not map-presence history. Four-target leaf complement is nondiscriminating; exact keys/paths carry isolation. Frozen projection/duplicate-target rejection not event-order accumulation. Earlier proposed/unpassed prose is dated, superseded only by explicit qualified conjunction.','memory-parent'),
 (225,'DET','Exact full replay and addressed-random noninterference, including no-draw and authoritative-draw fixtures.','Random-address changes may alter words, not guaranteed every pair. Character cannot read random words. Repeated prefix continuation is not unrelated-draw intervention by itself.','ledger-campaign2'),
 (251,'EPI','Equal permitted measurement at19/20 with different hidden potential and Overflow must preserve all declared immediate consumers.','Single source-record reference does not establish cross-event opaque truth-handle safety; later hedonic signals require separately admitted evidence, not copied Overflow.','ledger-agency-social'),
 (277,'SEM','Observer files, roles, grouping, feature/classification/recognition, causal claims, typed evidence and exact phase/lifecycle ownership remain distinct.','No natural segmentation/ontology inferred from bounded template rules. Missing differs from false; event classification is not learned action recognition. Explicit same-observer shared support differs from hidden ancestry. Strict lane cutoff and immutable historical envelope remain required. Complete requirement coverage belongs to final corpus gate, not this source-role review.','ledger-campaign2'),
 (309,'LEARN','The specified point-estimate learner distinguishes compatible, contradictory, zero-information and repeated bounds with exact later point response.','This is the accepted bounded learner obligation, not a theorem that compatible bounds cannot inform arbitrary probability distributions. Upper bounds/decay/richer posterior remain named reopen conditions.','ledger-agency-social'),
 (335,'MEM','Recency, selected-only retrieval reinforcement, decay, topK and exact tie controls define behavior rather than one historical equation.','Single retained measurement episode does not pass this lifecycle. Later GA is separate evidence; defining memory and vividness do not automatically prove every original comparison.','ledger-early'),
 (361,'REASON','Semantic motive/referent grouping, collective support, role/direction and zero-base/weak-base modifier controls remain explicit.','Disjoint evidence labels do not prove statistical independence. Aggregate union/order and nonparticipant scope remain open; exact quantitative grammar is not psychological calibration.','ledger-agency-social'),
 (387,'DECISION','Settled Auto, quiet/player-facing unresolved choice, exact distributions, frozen expression and independent execution.','Mode significance is not a commanded outcome. Neither normalized probabilities nor replay alone proves all controls. Multi-option scope must be named.','ledger-agency-social'),
 (413,'BIO','Early coupled decision variation, frozen expression, later feedback and common-seed probe preserve actual historical authorship.','Corpus calls controls distinguishable, while reviewed Refold/history-derived candidates can equal stored forms. Do not erase equality or claim that a representation must fail to pass. HQ012 must explicitly reconcile this comparator wording against research-method authority before whole-member acceptance.','ledger-agency-social'),
 (439,'COMMIT','Concrete live/retired/recurrent identity supplies bounded pressure independently of standing identity and observer knowledge.','Partial fulfillment/delegation/series identity are wider scope. Retirement is not deletion of historical identity or automatic observer correction.','ledger-agency-social'),
 (465,'ATTN','FiniteGA fixture43 models supplies explicit footprint/selection/probe qualification and retained law comparisons.','Promotion status is dated; general role inference, Need and Affect not acquired from GA. Independent focal invariance may coexist with association changes.','ledger-early'),
 (519,'BODY','Equal current physical level with different kinetic future, safe sensed pressure and separately held constitution/adaptation.','Historical EMB partial ownership status is superseded only by later scoped BODY/BIOLOGY. No stored-meter versus authored-reference equivalence outside the declared receiver/horizon.','ledger-agency-social'),
 (556,'BELIEF','Same truth/different admitted evidence and same belief/different goals; qualifying opportunity prevents non-event learning.','Evidence weight is not calibrated confidence despite colloquial confidently-wrong requirement. Known0 differs from unknown; next-cycle update does not retroactively alter appraisal.','ledger-core'),
 (589,'AFFECT','Independent appraisal contrasts, competing motives and later feedback; no forced action or relief-as-evidence.','Factors are experimental operands, not mandatory roots/product law. Scalar success is retained; independent feedback recipients require their own proof.','ledger-core'),
 (626,'WORK','Capacity+1 competition, protection, absent access with retained goal, later lawful cue recovery.','Dedicated store/cost scalar not assumed necessary; expired content cannot be recreated by a cue. Later intention/control results must be scoped independently.','ledger-core'),
 (659,'SKILL','Actual competence, belief and temporary impairment independently varied through practice/recovery.','Permission Boolean not skill; no implicit permanent unlearning from impairment or omniscient belief correction.','ledger-core'),
 (689,'SOCIAL','Independent observer access, mistaken belief and selective admitted correction.','Private intent not shared knowledge; expression is fallible, not universally trusted testimony. No general nested mentalizing from bounded reports.','ledger-core'),
 (721,'MULTI','Heterogeneous sources, shared/independent evidence and collective redundancy with a named receiving law.','Different task IDs alone are not source families. Correlation intervention must not erase legitimate motive distinctions. Whole corpus comparison needs exact shared/independent controls, not within-nucleus success alone.','ledger-core'),
 (757,'HABIT','Actual acquisition/reversal with matched belief/identity/body, history-sensitive versus belief/current-reward controls.','Habit does not entail a separate persistent root; addiction/withdrawal need their later distinct evidence. Hidden reward cannot silently correct belief.','ledger-core'),
 (791,'REL','Matched current person estimate with distinct admitted dyadic history and later response.','A richer person model may preserve the same history; no forced storage necessity. One rupture probe is not all grief/attachment.','ledger-core'),
 (824,'LONG','Actual multi-capability acquisition, retention, interference and relearning with stage-specific allowed mutations.','No authored learned state substitute, universal non-target byte preservation, or finite-horizon lifelong equivalence. Old missing goals text is historical intake, not current qualification; later composed scope remains component where declared.','ledger-residual'),
 (865,'TEMPLATE-HISTORY','Entry template is process guidance;0.26 name correction substantively changed comparison schema.','A template is not a new phenomenon or automatic authority for missing fields.','ledger-campaign2'),
 (888,'PROBE-CARRIAGE','Diagnostic observation, transient measurement content, persistent formation and recall are separately qualified stages.','Observation-only5/51-over-10 is not character-learning divergence; transient carriage is not persistent cognition.','probe-carriage'),
 (918,'MEMORY-PARENT','Corrected packet freeze, actual memory runtime, same-S0 count pair and accepted four-rule amendment preserve original sources.','Never-admitted58a491 family not a compatibility source; public/component split and prefix-not-antirollback limits remain. PHEN-MEM not passed by this single-episode target.','memory-parent'),
 (980,'PROMOTION','Explicit accepted fixture amendment qualifies ADAPT bounded; canonical1.11.0/0.27 promotion resolves digest discrepancy.','Draft181ce571 and historical0.26 commitments remain distinct, neither aliases nor retroactively invalid. Final prose current command/OPEN labels belong to dated annotation.','memory-parent')]
raw=(B/'sources'/SOURCE).read_bytes();assert Path(SOURCE).read_bytes()==raw
lines=raw.decode('utf-8-sig').splitlines(keepends=True);rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source']!=SOURCE:continue
  _,name,claim,limits,basis=max((s for s in specs if s[0]<=u['location']['startLine']),key=lambda s:s[0])
  assert ''.join(lines[u['location']['startLine']-1:u['location']['endLine']])==u['text']
  rows.append(dict(occurrenceId=u['id'],location=u['location'],text=u['text'],subject=name,role='CORPUS_REQUIREMENT_OR_DATED_ANNOTATION',disposition=claim,limits=limits,reviewBasis='campaign3-history-'+basis+'-rev1/review.json'))
assert {n for r in rows for n in range(r['location']['startLine'],r['location']['endLine']+1)}=={i+1 for i,l in enumerate(lines) if l.strip()}
evidence=[]
for name in sorted({r['reviewBasis'] for r in rows}):
 p=P/name;evidence.append(dict(path=p.as_posix(),sha256=sha(p)))
v=dict(status='CORPUS REQUIREMENTS/HISTORICAL ANNOTATIONS REVIEWED; EXIT DISPOSITIONS NOT AWARDED',source=dict(path=SOURCE,sha256=sha(B/'sources'/SOURCE)),rows=rows,evidence=evidence,obligations=['RO-C3-019','RO-C3-020','RO-C3-021'],remaining=['HQ012 must map each member requirement and comparator to exact admitted evidence, resolve BIO comparator-wording/equality tension under research-method authority, and assign explicit scope.','No clause/member promotion, changed corpus digest, representation retirement or fresh production execution.','Whole-source occurrence accounting is not whole-corpus qualification; governing source adequacy and other HQ011 roles remain open.'])
O.mkdir(exist_ok=True);save(O/'review.json',v)
c=dict(status=v['status'],originalOccurrences=len(rows),subjects=len(specs),indexedWholeOccurrenceLinks=1801+len(rows),reviewSha256=sha(O/'review.json'),checkerSha256=sha(__file__))
save(O/'check.json',c);print(json.dumps(c))
